请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-008

=== 用户原始指令 (query.txt) ===
帮我搞个听书卡片,点一下能跳到app里接着听

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我搞个听书卡片,点一下能跳到app里接着听",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "audiobook": {
      "statusLabel": {
        "type": "string",
        "description": "当前听书状态短标签",
        "sampleValue": "正在听"
      },
      "title": {
        "type": "string",
        "description": "当前听书作品名称",
        "sampleValue": "三体有声书"
      },
      "chapter": {
        "type": "string",
        "description": "当前播放章节展示文本",
        "sampleValue": "第 12 章"
      },
      "progressText": {
        "type": "string",
        "description": "当前听书进度展示文本",
        "sampleValue": "已听 32 分钟"
      },
      "actionLabel": {
        "type": "string",
        "description": "跳转应用继续听的动作短文案",
        "sampleValue": "继续听"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/music_fill.svg",
      "description": "音乐音符实心图标，适合用于音频播放、听书入口和当前播放内容识别。"
    }
  ]
}

